from __future__ import annotations

import hashlib
import json
import os
import shutil
import subprocess
from pathlib import Path


TASK_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_ROOT / "source"
FIXTURE_ROOT = TASK_ROOT / "fixtures"
OUTPUT_ROOT = TASK_ROOT / "outputs"
REPORT_PATH = OUTPUT_ROOT / "public_reproduction_report.json"


def execution_parent() -> Path:
    configured = os.environ.get("SCI_BENCH_EXEC_TMP")
    parent = Path(configured) if configured else TASK_ROOT / ".science_bench_build"
    parent.mkdir(parents=True, exist_ok=True)
    return parent


def source_digest() -> str:
    digest = hashlib.sha256()
    for path in sorted(SOURCE_ROOT.rglob("*")):
        if not path.is_file():
            continue
        if any(part in {".git", "__pycache__", "outputs"} for part in path.parts):
            continue
        digest.update(path.relative_to(SOURCE_ROOT).as_posix().encode("utf-8"))
        digest.update(path.read_bytes())
    return digest.hexdigest()[:20]


def write_report(payload: dict[str, object], exit_code: int) -> int:
    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    REPORT_PATH.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(REPORT_PATH.read_text(encoding="utf-8"), end="")
    return exit_code


def run_checked(command: list[str], *, cwd: Path, log_path: Path, timeout: int) -> None:
    completed = subprocess.run(
        command,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        timeout=timeout,
        check=False,
    )
    log_path.write_text(completed.stdout[-20000:], encoding="utf-8", errors="replace")
    if completed.returncode != 0:
        raise RuntimeError(f"command failed: {Path(command[0]).name}")


def find_executable(build_root: Path) -> Path:
    expected = build_root / "app" / "dftb+" / "dftb+"
    if expected.is_file() and os.access(expected, os.X_OK):
        return expected
    for path in build_root.rglob("dftb+"):
        if path.is_file() and os.access(path, os.X_OK):
            return path
    raise FileNotFoundError("compiled DFTB+ executable was not produced")


def build_executable(work_root: Path) -> Path:
    local_source = work_root / "source"
    build_root = work_root / "build"
    executable = build_root / "app" / "dftb+" / "dftb+"
    if executable.is_file() and os.access(executable, os.X_OK):
        return executable
    cmake = shutil.which("cmake")
    if cmake is None:
        raise RuntimeError("cmake is unavailable")
    run_checked(
        [
            cmake,
            "-S",
            str(local_source),
            "-B",
            str(build_root),
            "-DCMAKE_BUILD_TYPE=Release",
            "-DBUILD_EXPORTED_TARGETS_ONLY=FALSE",
            "-DWITH_API=OFF",
            "-DWITH_OMP=OFF",
            "-DWITH_TBLITE=OFF",
            "-DWITH_SDFTD3=OFF",
            "-DWITH_UNIT_TESTS=OFF",
            "-DWITH_PYTHON=OFF",
            "-DWITH_MPI=OFF",
        ],
        cwd=work_root,
        log_path=work_root / "configure.log",
        timeout=300,
    )
    run_checked(
        [cmake, "--build", str(build_root), "--parallel", "2"],
        cwd=work_root,
        log_path=work_root / "build.log",
        timeout=900,
    )
    return find_executable(build_root)


def run_case(executable: Path, run_root: Path, name: str) -> None:
    case_dir = run_root / "fixtures" / name
    completed = subprocess.run(
        [str(executable)],
        cwd=case_dir,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=180,
        check=False,
    )
    (case_dir / "runner.stdout").write_text(completed.stdout[-10000:], encoding="utf-8")
    (case_dir / "runner.stderr").write_text(completed.stderr[-10000:], encoding="utf-8")
    if completed.returncode != 0:
        raise RuntimeError(f"case {name} exited with {completed.returncode}")
    report = case_dir / "detailed.out"
    if not report.is_file():
        raise RuntimeError(f"case {name} did not write detailed.out")


def main() -> int:
    work_root: Path | None = None
    try:
        REPORT_PATH.unlink(missing_ok=True)
        digest = source_digest()
        work_root = execution_parent() / f"task085-public-{digest}"
        work_root.mkdir(parents=True, exist_ok=True)
        local_source = work_root / "source"
        if not local_source.exists():
            shutil.copytree(SOURCE_ROOT, local_source)
        executable = build_executable(work_root)

        run_root = work_root / "run"
        shutil.rmtree(run_root, ignore_errors=True)
        shutil.copytree(FIXTURE_ROOT, run_root / "fixtures")
        archive_names = sorted(
            path.name for path in (run_root / "fixtures").iterdir()
            if path.is_dir() and (path / "dftb_in.hsd").is_file()
        )
        if not archive_names:
            raise RuntimeError("no runnable archives found")
        for name in archive_names:
            run_case(executable, run_root, name)
        return write_report(
            {
                "schema_version": "1.0",
                "status": "workflow_completed",
            },
            0,
        )
    except Exception as exc:  # noqa: BLE001 - runner failures use a stable public status.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
            },
            2,
        )


if __name__ == "__main__":
    raise SystemExit(main())

