#"'!/usr/bin/env python3
"""Offline solvation regressions using a built dftb+ and H/C/N/O SK parameters.

Run: python solvation_consistency.py /path/to/dftb+ /path/to/mio-1-1

The geometries are independent of the archived workflow. Checks use equivalent
inputs, analytic surface integrals, and derivatives rather than stored reports.
"""

import argparse
import math
from pathlib import Path
import re
import subprocess
import tempfile
import unittest

# Constants and tabulated radii from the shipped manual/source, in Angstrom.
BOHR = 0.529177249
HARTREE_J = 4.3597441775e-18
KB = 0.00000316681534524639
DYN_CM = 1e-3 * (BOHR * 1e-10)**2 / HARTREE_J
RADII = {
    "vanDerWaalsRadiiD3": dict(H=1.09155, C=1.45515, N=1.31125, O=1.24085),
    "vanDerWaalsRadiiBondi": dict(H=1.10, C=1.70, N=1.55, O=1.52),
    "vanDerWaalsRadiiCosmo": dict(H=1.30, C=2.00, N=1.83, O=1.72),
    "AtomicRadii": dict(H=0.32, C=0.75, N=0.71, O=0.64),
}
TENSION = dict(H=4.2, C=12.3, N=-7.4, O=-5.7)
WATER = (("O", .13, -.08, .04), ("H", 1.075, .04, .12), ("H", -.12, .81, -.06))
METHANOL = (
    ("C", .2, -.1, .15), ("O", 1.61, -.05, .14), ("H", -.16, .925, .22),
    ("H", -.21, -.68, 1.01), ("H", -.19, -.57, -.76), ("H", 1.98, .79, .36),
)
AMMONIA = (
    ("N", .12, -.14, .05), ("H", .23, .81, .41),
    ("H", .95, -.59, .39), ("H", -.71, -.62, .4),
)


def values(data, method="Values", unit=None):
    modifier = f" [{unit}]" if unit else ""
    factor = {None: 1., "Bohr": 1. / BOHR, "AA": 1., "pm": 100.}[unit]
    entries = "; ".join(f"{key} = {val * factor:.16g}" for key, val in data.items())
    return f"{method}{modifier} {{ {entries} }}"


def sasa(radii="vanDerWaalsRadiiD3 {}", tension=TENSION, probe=1.28, width=.21):
    return f"""SASA {{
      ProbeRadius [AA] = {probe}
      Smoothing [AA] = {width}
      Offset [AA] = 1.1
      Tolerance = 1e-12
      AngularGrid = 230
      Radii = {radii}
      SurfaceTension = {values(tension)}
    }}"""


def solvent(epsilon=7.0, mass="[amu] = 92.14", density="[kg/l] = 0.867"):
    return f"""fromConstants {{
      Epsilon = {epsilon}
      MolecularMass {mass}
      Density {density}
    }}"""


def model(kind, radii="vanDerWaalsRadiiD3 {}", surface=True, solvent_input=None,
          state="gsolv", shift=0., temperature=298.15, cm5=None, hbond=False):
    if kind == "SASA":
        return sasa(radii)
    settings = f"""Solvent = {solvent_input or solvent()}
      State = "{state}"
      FreeEnergyShift = {shift}
      Temperature [Kelvin] = {temperature}
      Radii = {radii}
    """
    if kind == "Cosmo":
        settings += """RadiiScaling = 1.42
          AngularGrid = 194
          Solver = DomainDecomposition { MaxMoment = 7; Accuracy = 1e-11 }
        """
    else:
        settings += """BornScale = 1.35
          BornOffset [AA] = 0.012
          Descreening = Unity {}
        """
        if cm5:
            settings += f"CM5 {{ Radii = {cm5} }}'"\\n\"
        if surface:
            settings += f\"HBondCorr = {'Yes' if hbond else 'No'}\\n\"
            if hbond:
                settings += \"HBondStrength = Values { H = -.002; C = -.0003; N = -.0015; O = -.001 }\\n\"
    if surface:
        settings += sasa(radii)
    return f\"{kind} {{ {settings} }}\"


def read_tags(path):
    tags = {}
    key = None
    for line in path.read_text().splitlines():
        if \":\" in line:
            key = line.split(\":\")[0].strip()
            tags[key] = []
        elif key:
            tags[key].extend(float(word) for word in line.split())
    return tags


class SolvationConsistency(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory(prefix=\"dftb-solvation-\")
        cls.root = Path(cls.temp.name)
        cls.nrun = 0

    @classmethod
    def tearDownClass(cls):
        cls.temp.cleanup()

    def run_calc(self, atoms, solvation=None, species=None, charge=0., analysis=\"\", hsd=None):
        type(self).nrun += 1
        work = self.root / str(self.nrun)
        work.mkdir()
        names = species or sorted({atom[0] for atom in atoms})
        if hsd is None:
            geometry = f\"{len(atoms)} C\\n\" + \" \".join(names) + \"\\n\"
            for i, (symbol, *xyz) in enumerate(atoms):
                geometry += f\"{i+1} {names.index(symbol)+1} \" + \" \".join(f\"{x:.16g}\" for x in xyz) + \"\\n\"
            hsd = f\"\"\"Geometry = GenFormat {{ {geometry} }}
              Hamiltonian = DFTB {{
                SCC = Yes
                SccTolerance = 1e-11
                MaxSCCIterations = 300
                Charge = {charge}
                MaxAngularMomentum {{ H = \"s\"; C = \"p\"; N = \"p\"; O = \"p\" }}
                SlaterKosterFiles = Type2FileNames {{
                  Prefix = \"{PARAMETERS}/\"
                  Separator = \"-\"
                  Suffix = \".skf\"
                }}
                {('Solvation = ' + solvation) if solvation else ''}
              }}
              Analysis {{ PrintForces = Yes; {analysis} }}
              Options {{ WriteResultsTag = Yes }}
              ParserOptions {{ ParserVersion = 14 }}
            \"\"\"
        (work / \"dftb_in.hsd\").write_text(hsd)
        process = subprocess.run([str(EXECUTABLE)], cwd=work, capture_output=True, text=True, timeout=120)
        self.assertEqual(process.returncode, 0, process.stdout[-4000:] + process.stderr)
        detail = (work / \"detailed.out\").read_text()
        self.assertIn(\"SCC converged\", detail)
        result = read_tags(work / \"results.tag\")
        match = re.search(r\"Solvation energy:\\s*(\\S+)\", detail)
        result[\"solvation\"] = [float(match[1]) if match else 0.]
        result[\"processed\"] = (work / \"dftb_pin.hsd\").read_text()
        if (work / \"dftbp.cosmo\").exists():
            result[\"cosmo\"] = (work / \"dftbp.cosmo\").read_text()
        return result

    def assert_observables(self, first, second, order=None, tolerance=2e-8):
        for key in (\"total_energy\", \"solvation\", \"gross_atomic_charges\", \"forces\"):
            expected = first[key]
            if order is not None and key in (\"gross_atomic_charges\", \"forces\"):
                stride = 3 if key == \"forces\" else 1
                expected = [x for i in order for x in expected[i*stride:(i+1)*stride]]
            self.assertEqual(len(expected), len(second[key]))
            for x, y in zip(expected, second[key]):
                self.assertAlmostEqual(x, y, delta=tolerance, msg=key)

    def test_atom_and_species_order(self):
        for atoms in (WATER, METHANOL, AMMONIA):
            for kind in (\"SASA\", \"Cosmo\", \"GeneralisedBorn\"):
                with self.subTest(atoms=atoms[0][0], model=kind):
                    settings = model(kind)
                    base = self.run_calc(atoms, settings)
                    order = list(reversed(range(len(atoms))))
                    reordered = self.run_calc([atoms[i] for i in order], settings)
                    self.assert_observables(base, reordered, order)
                    names = sorted({a[0] for a in atoms}, reverse=True)
                    retyped = self.run_calc(atoms, settings, species=names)
                    self.assert_observables(base, retyped)
        settings = model(\"GeneralisedBorn\", hbond=True)
        base = self.run_calc(METHANOL, settings)
        order = [3, 5, 0, 4, 1, 2]
        self.assert_observables(base, self.run_calc([METHANOL[i] for i in order], settings), order)

    def test_radius_units_defaults_and_overrides(self):
        for method in (\"vanDerWaalsRadiiD3\", \"vanDerWaalsRadiiBondi\", \"vanDerWaalsRadiiCosmo\"):
            radii = RADII[method]
            for kind in (\"SASA\", \"Cosmo\", \"GeneralisedBorn\"):
                with self.subTest(method=method, model=kind):
                    base = self.run_calc(WATER, model(kind, f\"{method} {{}}\"))
                    for unit in (\"AA\", \"pm\", \"Bohr\"):
                        explicit = self.run_calc(WATER, model(kind, values(radii, unit=unit)))
                        self.assert_observables(base, explicit)
                        defaults = self.run_calc(WATER, model(kind, values({}, method, unit)))
                        self.assert_observables(base, defaults)
                    modified = dict(radii, H=1.18)
                    explicit = self.run_calc(WATER, model(kind, values(modified, unit=\"Bohr\")))
                    for unit in (\"AA\", \"pm\"):
                        partial = self.run_calc(WATER, model(kind, values({\"H\": 1.18}, method, unit)))
                        self.assert_observables(explicit, partial)
                        replay = self.run_calc(WATER, hsd=partial[\"processed\"])
                        self.assert_observables(partial, replay)

    def test_cm5_radius_units(self):
        radii = RADII[\"AtomicRadii\"]
        base = self.run_calc(AMMONIA, model(\"GeneralisedBorn\", cm5=\"AtomicRadii {}\"))
        for unit in (\"AA\", \"Bohr\", \"pm\"):
            with self.subTest(unit=unit):
                explicit = self.run_calc(AMMONIA, model(\"GeneralisedBorn\", cm5=values(radii, unit=unit)))
                self.assert_observables(base, explicit)
                defaults = self.run_calc(AMMONIA, model(\"GeneralisedBorn\", cm5=values({}, \"AtomicRadii\", unit)))
                self.assert_observables(base, defaults)
                modified = dict(radii, H=.36)
                partial = self.run_calc(AMMONIA, model(\"GeneralisedBorn\", cm5=values({\"H\": .36}, \"AtomicRadii\", unit)))
                explicit = self.run_calc(AMMONIA, model(\"GeneralisedBorn\", cm5=values(modified, unit=\"Bohr\")))
                self.assert_observables(explicit, partial)

    def test_solvent_units_and_reference_states(self):
        # Convert molecular mass independently of density so errors cannot cancel.
        mass_kg = 92.14 / .00054857990945 * 9.10938356e-31
        equivalents = (
            'fromName { \"toluene\" }',
            solvent(mass=f\"[kg] = {mass_kg:.16g}\"),
            solvent(mass=f\"[g] = {mass_kg * 1000:.16g}\"),
            solvent(density=\"[kg/m"'^3] = 867"),
            solvent(density="[g/l] = 867"),
            solvent(density="[g/m''^3] = 867000"),
            solvent(density="[g/meter''^3] = 867000"),
        )
        for kind in ("Cosmo", "GeneralisedBorn"):
            base = self.run_calc(WATER, model(kind, state="reference"))
            for descriptor in equivalents:
                with self.subTest(model=kind, solvent=descriptor):
                    self.assert_observables(base, self.run_calc(WATER, model(kind, state="reference", solvent_input=descriptor)))
            for temperature in (273.15, 325.):
                bare = self.run_calc(WATER, model(kind, temperature=temperature))
                shifted = self.run_calc(WATER, model(kind, temperature=temperature, state="mol1bar", shift=.0012))
                expected = .0012 + KB * temperature * math.log(24.79 * temperature / 298.15)
                self.assertAlmostEqual(shifted["total_energy"][0] - bare["total_energy"][0], expected, delta=2e-10)
                for x, y in zip(bare["forces"], shifted["forces"]):
                    self.assertAlmostEqual(x, y, delta=2e-9)

    def test_surface_area_and_units(self):
        # An isolated smoothed sphere has area 4*pi*(R''^2 + w''^2/5).
        for radius, probe, width in ((1.39, 1.12, .17), (1.68, .83, .29)):
            atoms = (("O", .7, -.4, .1),)
            settings = sasa(values({"O": radius}, unit="Bohr"), {"O": 8.7}, probe, width)
            result = self.run_calc(atoms, settings)
            area = 4 * math.pi * ((radius + probe)**2 + width**2 / 5) / BOHR**2
            self.assertAlmostEqual(result["solvation"][0], 8.7 * DYN_CM * area, delta=6e-11)
            self.assertLess(max(abs(f) for f in result["forces"]), 1e-10)
        # A smaller concentric-radius sphere completely inside another atom'"'s
        # cavity contributes no exposed area, regardless of which atom is first.
        atoms = ((\"O\", 0., 0., 0.), (\"H\", .94, .02, 0.))
        radii = values({\"O\": 3.4, \"H\": .4}, unit=\"Bohr\")
        hidden = self.run_calc(atoms, sasa(radii, {\"O\": 0., \"H\": 11.}))
        self.assertAlmostEqual(hidden[\"solvation\"][0], 0., delta=1e-10)
        self.assert_observables(hidden, self.run_calc(atoms[::-1], sasa(radii, {\"O\": 0., \"H\": 11.})), [1, 0])

    def test_energy_derivatives_and_translation(self):
        # A general displacement tests all Cartesian force components at once.
        direction = ((.17, -.31, .23), (-.29, .11, .07), (.13, .19, -.37))
        step = 2e-4  # Bohr
        for kind in (\"SASA\", \"Cosmo\", \"GeneralisedBorn\"):
            settings = model(kind)
            base = self.run_calc(WATER, settings)
            energies = []
            for sign in (-1, 1):
                atoms = [(a[0], *(x + sign * step * BOHR * d for x, d in zip(a[1:], v))) for a, v in zip(WATER, direction)]
                energies.append(self.run_calc(atoms, settings)[\"total_energy\"][0])
            gradient = (energies[1] - energies[0]) / (2 * step)
            projected_force = sum(f * d for f, d in zip(base[\"forces\"], sum(direction, ())))
            self.assertAlmostEqual(gradient, -projected_force, delta=2e-7, msg=kind)
            for axis in range(3):
                self.assertAlmostEqual(sum(base[\"forces\"][axis::3]), 0., delta=2e-9)
            shifted = [(a[0], a[1] + .51, a[2] - .32, a[3] + .28) for a in WATER]
            self.assert_observables(base, self.run_calc(shifted, settings))

    def test_cosmo_report(self):
        for epsilon in (1., 4.6, \"Inf\"):
            for charge in (0., 1.):
                with self.subTest(epsilon=epsilon, charge=charge):
                    settings = model(\"Cosmo\", surface=False, solvent_input=solvent(epsilon))
                    result = self.run_calc(WATER, settings, charge=charge, analysis=\"WriteCosmoFile = Yes\")
                    report = result[\"cosmo\"]
                    dielectric = float(re.search(r\"Dielectric energy.*?=\\s*(\\S+)\", report)[1])
                    self.assertAlmostEqual(dielectric, result[\"solvation\"][0], delta=2e-9)
                    self.assertLessEqual(dielectric, 1e-10)
                    segments = report.split(\""'$segment_information")[1].splitlines()
                    for line in segments:
                        if not line.strip() or line.lstrip().startswith("#"):
                            continue
                        data = line.split()
                        position = [float(x) for x in data[2:5]]  # Bohr
                        potential = sum(q / math.dist(position, [x / BOHR for x in atom[1:]]) for q, atom in zip(result["gross_atomic_charges"], WATER)) / BOHR
                        self.assertAlmostEqual(float(data[8]), potential, delta=3e-9)
        # Surface and reference-state contributions do not enter dielectric energy.
        polar = self.run_calc(WATER, model("Cosmo", surface=False), analysis="WriteCosmoFile = Yes")
        combined = self.run_calc(WATER, model("Cosmo", shift=.0017, state="mol1bar"), analysis="WriteCosmoFile = Yes")
        nonpolar = self.run_calc(WATER, model("SASA"))
        shift = .0017 + KB * 298.15 * math.log(24.79)
        expected = polar["solvation"][0] + nonpolar["solvation"][0] + shift
        self.assertAlmostEqual(combined["solvation"][0], expected, delta=2e-9)
        for result in (polar, combined):
            dielectric = float(re.search(r"Dielectric energy.*?='"\\s*(\\S+)\", result[\"cosmo\"])[1])
            self.assertAlmostEqual(dielectric, polar[\"solvation\"][0], delta=2e-9)


